function evidence = f90_xauto07_extract_candidate_evidence_core(modelPath, outputDir)
%F90_XAUTO07_EXTRACT_CANDIDATE_EVIDENCE_CORE_CORE_CORE Replay the five public-input scales.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot,sharedRoot,publicOutputRoot]=localRoots("F90-XAUTO-07");
addpath(sharedRoot,"-begin"); addpath(publicOutputRoot,"-begin");
cleanup=onCleanup(@()localRemovePaths(sharedRoot,publicOutputRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xauto07-fixed-evidence.v1", ...
    "task_id","F90-XAUTO-07","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@(~,~)5.0,"postprocess",@localPostprocess, ...
    "static_audit",@localAudit,"evidence_sample_s",0.005);
evidence=simuverity_run_candidate_evidence(modelPath,outputDir,spec);
evidence=localFinalize(evidence,outputDir);
end

function rows=localOutputs
rows=localRows(["driver_input","motor_torque","phase_currents", ...
    "vehicle_speed"],[2 4 3 1]);
rows(1).interpolation="previous";
end

function inputs=localInputs(scenario,~)
inputs=struct("ev_drive_input",struct( ...
    "acceleration_scale",double(scenario.acceleration_scale), ...
    "brake_scale",double(scenario.brake_scale)));
end

function requested=localRequested(scenario,~)
requested=struct("acceleration_scale",double(scenario.acceleration_scale), ...
    "brake_scale",double(scenario.brake_scale));
end

function row=localPostprocess(row,outputs,~,~)
t=double(outputs.time_s(:)); driver=double(outputs.driver_input);
torque=double(outputs.motor_torque); currents=double(outputs.phase_currents);
speed=double(outputs.vehicle_speed(:,1)); measured=torque(:,2);
positive=measured(measured>1); negative=measured(measured<-1);
allValues=[t;driver(:);torque(:);currents(:);speed(:)];
row.metrics=struct( ...
    "driver_sample_count",numel(t),"torque_sample_count",numel(t), ...
    "phase_current_sample_count",numel(t),"vehicle_sample_count",numel(t), ...
    "vehicle_speed_final_kph",speed(end),"vehicle_speed_max_kph",max(speed), ...
    "vehicle_speed_range_kph",max(speed)-min(speed), ...
    "measured_torque_min_Nm",min(measured), ...
    "measured_torque_max_Nm",max(measured), ...
    "measured_torque_positive_mean_Nm",localMean(positive), ...
    "measured_torque_negative_mean_Nm",localMean(negative), ...
    "torque_tracking_rmse_Nm",sqrt(mean((measured-torque(:,1)).^2)), ...
    "torque_estimation_rmse_Nm",sqrt(mean((torque(:,3)-measured).^2)), ...
    "phase_current_rms_A",sqrt(mean(currents(:).^2)), ...
    "phase_current_abs_max_A",max(abs(currents),[],"all"), ...
    "motoring_present",any(measured>5),"generating_present",any(measured<-5), ...
    "torque_sign_changes",nnz(diff(sign(measured))~=0), ...
    "all_finite",all(isfinite(allValues)));
row.outputs=outputs; row.offline_metrics=row.metrics;
row.valid=row.output_contract.all_required_pass&&row.metrics.all_finite&& ...
    numel(t)>=100;
end

function descriptor=localDescriptor(channels,samples,units)
descriptor=struct("channels",channels,"samples",samples,"units",{units});
end

function value=localMean(values)
if isempty(values),value=0.0;else,value=mean(values);end
end

function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
semantic=structure.semantic_types;
connected=structure.connected_output_count==numel(spec.output_contract)&& ...
    structure.nontrivial_output_source_count==numel(spec.output_contract);
dynamic=structure.dynamic_block_count>=3||structure.physical_connection_block_count>=5;
closed=connected&&dynamic&&(structure.signal_cycle_present|| ...
    structure.physical_connection_block_count>0||structure.block_count>=20);
electrical=any(contains(semantic,["battery","dc source","converter", ...
    "inverter","three-phase","electrical"]))||closed;
machine=any(contains(semantic,["permanent magnet","synchronous machine", ...
    "pmsm","motor"]))||closed;
mechanical=any(contains(semantic,["gear","differential","axle", ...
    "vehicle","mass"]))||closed;
audit=struct( ...
    "battery_and_dc_link",electrical, ...
    "controlled_three_phase_converter",electrical&&closed, ...
    "interior_permanent_magnet_motor",machine, ...
    "closed_loop_phase_current_control",closed, ...
    "torque_reference_and_estimation",connected&&closed, ...
    "fixed_ratio_gear_and_axle",mechanical, ...
    "finite_mass_vehicle_dynamics",mechanical&&dynamic, ...
    "closed_driver_drive_vehicle_feedback",closed, ...
    "connected_public_output_count",structure.connected_output_count, ...
    "qualification_basis","candidate topology and published output bindings");
end

function evidence=localFinalize(evidence,outputDir)
rows=evidence.scenarios;
scenarioDir=fullfile(outputDir,"scenario_data");
if ~isfolder(scenarioDir),mkdir(scenarioDir);end
for index=1:numel(rows)
    outputs=rows(index).outputs;t=double(outputs.time_s(:));
    rows(index).inputs=rows(index).requested_inputs;
    rows(index).logs=struct( ...
        "driver_input",localDescriptor(2,numel(t),{"1","1"}), ...
        "motor_torque",localDescriptor(4,numel(t),{"N*m","N*m","N*m","N*m"}), ...
        "phase_currents",localDescriptor(3,numel(t),{"A","A","A"}), ...
        "vehicle_speed",localDescriptor(1,numel(t),{"km/h"}));
    data=struct("driver_time_s",t,"driver_input",double(outputs.driver_input), ...
        "torque_time_s",t,"torque_Nm",double(outputs.motor_torque), ...
        "phase_current_time_s",t,"phase_currents_A",double(outputs.phase_currents), ...
        "vehicle_time_s",t,"vehicle_speed_kph",double(outputs.vehicle_speed(:,1)));
    dataFile=fullfile(scenarioDir,string(rows(index).id)+".mat");
    save(dataFile,"data","-v7.3");
    rows(index).data_file="scenario_data/"+string(rows(index).id)+".mat";
    rows(index).data_file_file_presence=localFilePresence(dataFile);
    rows(index).canonical_data_file_presence=rows(index).data_file_file_presence;
end
evidence.scenarios=rows;
evidence.evaluation_subject="candidate";
evidence.simulate_pass=~isempty(rows)&&all([rows.simulation_pass]);
evidence.all_official_evidence_valid=~isempty(rows)&&all([rows.valid]);
evidence.runtime_model_unchanged=evidence.binding_preserved;
evidence.structure=evidence.static_audit;
evidence.EVIDENCE_COMPLETE=evidence.score_inputs_valid;
evidence.evidence_complete=evidence.EVIDENCE_COMPLETE;
localWriteJson(fullfile(outputDir,"evidence.json"),evidence);
end

function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
        rows(k).width=widths(k);end
end

function [taskRoot,sharedRoot,publicOutputRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
publicOutputRoot=fullfile(repoRoot,"scripts","unified","public_output");
end

function localRemovePaths(sharedRoot,publicOutputRoot)
try,rmpath(sharedRoot);catch,end
try,rmpath(publicOutputRoot);catch,end
end

function binding = localFilePresence(pathIn)
assert(isfile(pathIn), "SimuVerity:FileMissing", "Required file is missing: %s", pathIn);
binding = "present";
end

function localWriteJson(path,value)
temporary=string(path)+".staging-"+string(java.util.UUID.randomUUID);
fid=fopen(temporary,"w","n","UTF-8");assert(fid>=0,"SimuVerity:F90:XAUTO07:Write", ...
    "Cannot write candidate evidence.");cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,jsonencode(value,PrettyPrint=true),"char");clear cleanup
assert(movefile(temporary,path,"f"),"SimuVerity:F90:XAUTO07:Publish", ...
    "Cannot publish candidate evidence.");
end
